#: Declared python kind -> whether the column
#: holds a number, resolved from the model's own annotations.
def _numeric_fields(capability_id: str) -> Dict[str, str]:
    import typing

    model = models.MODELS.get(capability_id)
    if model is None:
        return {}
    try:
        hints = typing.get_type_hints(model)
    except Exception:  # noqa: BLE001 - an unresolved hint simply is not numeric
        hints = {}
    out: Dict[str, str] = {}
    for name in model.FIELDS:
        hint = hints.get(name)
        if hint is float:
            out[name] = "float"
        elif hint is int:
            out[name] = "int"
    return out


def _reject(status: int, field: str, reason: str,
            allowed: Optional[list] = None, message: str = "") -> JSONResponse:
    body: Dict[str, Any] = {
        "ok": False,
        "error": message or ("%s rejected: %s" % (field, reason)),
        "rejected_field": field,
        "rejection_reason": reason,
    }
    headers = {
        "X-Rejected-Field": json.dumps(field),
        "X-Rejection-Reason": reason,
    }
    if allowed:
        body["allowed_values"] = list(allowed)
        headers["X-Allowed-Values"] = json.dumps(list(allowed))
    return JSONResponse(status_code=status, content=body, headers=headers)


def validate_payload(capability_id: str, payload: Dict[str, Any]) -> Optional[JSONResponse]:
    """Only the capability's own declared fields are validated."""
    model = models.MODELS.get(capability_id)
    if model is None:
        return None
    rules = model.constraints()
    numeric = _numeric_fields(capability_id)
    for name in model.FIELDS:
        rule = rules.get(name) or {}
        value = payload.get(name)
        if rule.get("required") and value in (None, ""):
            return _reject(422, name, "missing_required", rule.get("allowed_values"))
        if value in (None, ""):
            continue
        allowed = rule.get("allowed_values")
        if allowed and value not in allowed:
            return _reject(422, name, "not_allowed", allowed)
        limit = rule.get("max_length")
        if limit and isinstance(value, str) and len(value) > int(limit):
            return _reject(422, name, "too_long",
                           message="%s may be at most %s characters" % (name, limit))
        kind = numeric.get(name)
        if kind:
            try:
                number = float(value)
            except (TypeError, ValueError):
                return _reject(422, name, "not_a_number")
            # NaN and the infinities are type-valid floats and poison both the
            # store and JSON encoding: refuse them at the edge.
            if not math.isfinite(number):
                return _reject(422, name, "not_a_number")
            if rule.get("min") is not None and number < float(rule["min"]):
                return _reject(422, name, "below_minimum")
    return None


def _handler_for(capability_id: str):
    module = importlib.import_module("app.actions." + capability_id.replace("-", "_"))
    return getattr(module, "handle")


def _unknown(capability_id: str) -> JSONResponse:
    return JSONResponse(
        status_code=404,
        content={"ok": False, "error": "unknown capability: %s" % capability_id},
    )


def _body(raw: Any) -> Dict[str, Any]:
    return dict(raw) if isinstance(raw, dict) else {}


@router.post("/{capability_id}")
async def create_record(capability_id: str, request: Request,
                        principal: Principal = Depends(security.require_principal)):
    model = models.MODELS.get(capability_id)
    if model is None:
        return _unknown(capability_id)
    security.require_permission(principal, security.permission_for(capability_id))
    declared_length = request.headers.get("content-length")
    if declared_length:
        try:
            if int(declared_length) > MAX_BODY_BYTES:
                return JSONResponse(status_code=413, content={
                    "ok": False,
                    "error": "request body exceeds %d bytes" % MAX_BODY_BYTES,
                })
        except (TypeError, ValueError):
            pass
    try:
        payload = _body(await request.json())
    except Exception:
        payload = {}
    refusal = validate_payload(capability_id, payload)
    if refusal is not None:
        return refusal
    try:
        result = _handler_for(capability_id)(payload)
    except Exception as exc:  # noqa: BLE001 - a handler failure is a refusal, not a 500
        return JSONResponse(status_code=200, content={
            "ok": False,
            "error": security.redact("%s: %s" % (type(exc).__name__, exc)),
            "authority": authority.envelope(),
        })
    if not isinstance(result, dict):
        result = {"ok": False, "error": "handler returned no envelope"}
    if result.get("ok") is False:
        return JSONResponse(status_code=200, content={
            "ok": False,
            "error": security.redact(result.get("error") or "capability refused"),
            "block": result.get("block"),
            "authority": authority.envelope(),
        })
    try:
        stored = store.save(model.entity(), payload, principal.tenant_id)
    except Exception as exc:  # noqa: BLE001 - persistence failure is a refusal, not a 500
        return JSONResponse(status_code=200, content={
            "ok": False,
            "error": security.redact("not stored: %s: %s" % (type(exc).__name__, exc)),
            "authority": authority.envelope(),
        })
    return {
        "ok": True,
        "stored": stored,
        "result": result.get("result"),
        "blocks": result.get("blocks"),
        "authority": authority.envelope(),
        "principal": principal.label(),
    }


@router.get("/{capability_id}")
def list_records(capability_id: str,
                 principal: Principal = Depends(security.require_principal)):
    model = models.MODELS.get(capability_id)
    if model is None:
        return _unknown(capability_id)
    security.require_permission(principal, "read")
    items = store.list_all(model.entity(), tenant_id=principal.tenant_id)
    return {
        "ok": True,
        "items": items,
        "total": len(items),
        "authority": authority.envelope(),
        "principal": principal.label(),
    }


@router.get("/{capability_id}/{record_id}")
def read_record(capability_id: str, record_id: str,
                principal: Principal = Depends(security.require_principal)):
    model = models.MODELS.get(capability_id)
    if model is None:
        return _unknown(capability_id)
    security.require_permission(principal, "read")
    record = store.get(model.entity(), record_id, principal.tenant_id)
    if record is None:
        # 404, not 403: a cross-tenant read must not leak that the row exists.
        return JSONResponse(status_code=404, content={
            "ok": False,
            "error": "record not found",
            "authority": authority.envelope(),
        })
    return {
        "ok": True,
        "record": record,
        "authority": authority.envelope(),
        "principal": principal.label(),
    }

"""double_entry_ledger -- balanced journal entries for wallets, transfers and
payouts. Every movement is recorded as a debit and a matching credit so the
book balances and each balance can be traced to its postings."""

from __future__ import annotations

from typing import Any, Dict, List

from app import formulas
from app.block_inputs import default_block_action, prepare_block_input
from app.dispatch import execute

AUTHORED_BY = "codewhale exec"

CAPABILITY_ID = "double_entry_ledger"
ENTITY = "double_entry_ledger"
BLOCK_IDS: List[str] = [
    "finance_canonical_model",
    "finance_reconciliation",
    "transaction_state_machine",
    "database",
]
BLOCK_DEFAULT_ACTIONS: Dict[str, Any] = {
    block_id: default_block_action(block_id) for block_id in BLOCK_IDS
}


def _failed(answer: Any) -> bool:
    return (not isinstance(answer, dict)
            or answer.get("status") == "error"
            or answer.get("ok") is False)


def handle(payload: Dict[str, Any]) -> Dict[str, Any]:
    record = dict(payload or {})
    postings = [
        {"side": "debit", "amount": record.get("amount"),
         "wallet_ref": record.get("wallet_ref"),
         "account": record.get("debit_account") or "wallet"},
        {"side": "credit", "amount": record.get("amount"),
         "wallet_ref": record.get("wallet_ref"),
         "account": record.get("credit_account") or "settlement"},
    ]
    answers: Dict[str, Any] = {}
    for block_id in BLOCK_IDS:
        prepared = prepare_block_input(block_id, record, CAPABILITY_ID)
        if block_id == "finance_reconciliation":
            prepared["ledger_entries"] = [
                {"reference": record.get("reference"), "amount": record.get("amount"),
                 "wallet_ref": record.get("wallet_ref"), "side": "debit"}
            ]
            prepared["statement_lines"] = []
        answer = execute(block_id, prepared, action=BLOCK_DEFAULT_ACTIONS.get(block_id))
        if _failed(answer):
            return {"ok": False, "block": block_id,
                    "error": "%s refused the entry: %s" % (block_id, answer.get("error"))}
        answers[block_id] = answer

    balance = formulas.journal_balance(postings)
    traced = formulas.wallet_balance(postings, record.get("wallet_ref"))
    canonical = (answers.get("finance_canonical_model") or {}).get("canonical") or {}
    return {
        "ok": True,
        "result": {
            "entry_balanced": balance,
            "wallet_balance": traced,
            "canonical": canonical,
            "postings": postings,
            "state": (answers.get("transaction_state_machine") or {}).get("state"),
            "stored_columns": (answers.get("database") or {}).get("columns"),
            "unmatched_ledger": (answers.get("finance_reconciliation") or {}).get("unmatched_ledger"),
        },
        "blocks": sorted(answers),
    }
