        return cls.ENTITY or str(cls.__name__).lower()

    @classmethod
    def required_fields(cls) -> List[str]:
        rules = cls.constraints()
        return [name for name in cls.FIELDS if (rules.get(name) or {}).get("required")]

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "_Model":
        obj = cls()
