"""Request security: authenticate, authorize, and fail closed.

Authentication answers 401 and authorization answers 403; a cross-tenant read
answers 404 so existence never leaks. Every route that touches tenant data goes
through :func:`require_principal`.
"""

from __future__ import annotations

from typing import Any, Optional

import re

from fastapi import Header, HTTPException

from app import config, tenancy
from app.tenancy import Principal

AUTHORED_BY = "codewhale exec"

#: ``[redacted]host`` -> ``[redacted]host``. A
#: driver error can quote the DSN, so the credential is stripped before that
#: text can reach a log line or an error body.
_CREDENTIALS_IN_URL = re.compile(r"(://[^:/@\s]+):[^@\s]+@")

#: permission each capability needs to be written through.
CAPABILITY_PERMISSIONS = {
    "double_entry_ledger": "write",
    "wallet_transfers_and_payouts": "move_money",
    "kyc_checks_with_id_documents": "write",
    "onboarding_approval_queue": "approve",
    "daily_bank_statement_reconciliation": "reconcile",
    "staff_workbench_and_dashboards": "read",
    "role_based_access_and_audit": "manage_roles",
}

_ROLE_PERMISSIONS = {
    "admin": {"read", "write", "approve", "move_money", "manage_roles", "reconcile"},
    "compliance_officer": {"read", "approve", "reconcile"},
    "operator": {"read", "write", "move_money", "reconcile"},
}


def permits(principal: Principal, permission: str) -> bool:
    if not principal.authenticated:
        return False
    return permission in _ROLE_PERMISSIONS.get(principal.role, set())


def check_approver(officer: str) -> dict:
    """Whether this named approver may decide.

    The operator declares who is competent to approve (APPROVED_PRINCIPALS).
    When that list is set, a name outside it is refused -- a free-text approver
    is never trusted, and a safety escalation cannot be waved through by
    typing a title. When the list is unset there is nothing to check against,
    so the approver is recorded as unverified rather than silently trusted.
    """
    name = str(officer or "").strip()
    if not name:
        return {"ok": False, "error": "a decision must name the person making it",
                "approver_required": True, "approver": None, "verified": False}
    declared = config.APPROVED_PRINCIPALS
    if not declared:
        return {"ok": True, "approver": name, "verified": False,
                "reason": "no APPROVED_PRINCIPALS configured: approver recorded unverified"}
    if name not in declared:
        return {"ok": False, "approver": name, "verified": False,
                "error": "%s is not an approved principal" % name,
                "approved_principals": list(declared)}
    return {"ok": True, "approver": name, "verified": True}


def require_principal(authorization: Optional[str] = Header(default=None)) -> Principal:
    """The authenticated principal, or HTTP 401."""
    principal = tenancy.resolve_principal({"Authorization": authorization or ""})
    if not principal.authenticated:
        raise HTTPException(status_code=401, detail="unauthorized: a valid bearer token is required")
    return principal


def require_permission(principal: Principal, permission: str) -> None:
    if not permits(principal, permission):
        raise HTTPException(
            status_code=403,
            detail="forbidden: role %s may not %s" % (principal.role, permission),
        )


def permission_for(capability_id: str) -> str:
    return CAPABILITY_PERMISSIONS.get(capability_id, "write")


def redact(value: Any) -> str:
    """Never let a token or a database credential reach a log line or an
    error body."""
    text = str(value or "")
    secrets = [config.PLATFORM_TOKEN, config.DATABASE_URL, config.SENTRY_DSN]
    secrets.extend(config.TENANT_TOKENS)
    for secret in secrets:
        if secret and secret in text:
            text = text.replace(secret, "[redacted]")
    return _CREDENTIALS_IN_URL.sub(r"\1:[redacted]@", text)

