def probe() -> dict:
    """Ask the live database whether it answers, on its own backend."""
    try:
        with connect() as conn:
            value = conn.execute(text("SELECT 1")).scalar()
        return {"ok": value == 1, "backend": backend()}
    except Exception as exc:  # noqa: BLE001 - the probe reports, never raises
        return {"ok": False, "backend": backend(), "error": "%s: %s" % (type(exc).__name__, exc)}


def dispose() -> None:
    global _ENGINE
    if _ENGINE is not None:
