        _ENGINE = None


def table_names() -> list:
    """Tables currently in the database (used by health and backup)."""
    with connect() as conn:
        rows = conn.exec_driver_sql(
            "SELECT name FROM sqlite_master WHERE type='table'"
            if not is_postgres()
            else "SELECT tablename FROM pg_catalog.pg_tables WHERE schemaname='public'"
        ).fetchall()
    return sorted(str(r[0]) for r in rows)


